jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // ── Audience gate ─────────────────────────────────────────────────
  var ALLOWED = {
    "andrew_nemiroff@colpal.com": 1,
    "jared_lerner@colpal.com": 1,
  };
  var ident = (eli.tools && typeof eli.tools.userIdentity === "function")
    ? eli.tools.userIdentity() : {};
  var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
  if (!ALLOWED[userEmail]) {
    eli.log.event("tool", "clause_library_skip", { reason: "not_allowed", email: userEmail });
    return;
  }

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _slug(s) {
    return String(s == null ? "" : s)
      .toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").replace(/_+/g, "_");
  }
  function _clauseId(name, variant) {
    return _slug(name || "_") + "__" + _slug(variant || "_");
  }
  function _toast(msg, kind) {
    if (typeof showToast === "function") showToast(msg, kind || "info");
  }

  // ── In-memory state (rendered to DOM on every change) ─────────────
  var _state = {
    clauses: [],
    filter: "",
    variantFilter: "",
    editId: null,            // id of clause being edited (null = no edit panel)
    creating: false,         // creating a new clause via the "+ New" button
    captureMode: false,      // creating via "Capture from Word"
  };

  function _loadAll() {
    return eli.storage.getAll("bd_clauses").then(function (rows) {
      _state.clauses = (rows || []).sort(function (a, b) {
        // Group by name, then variant.
        if (a.name !== b.name) return String(a.name).localeCompare(String(b.name));
        return String(a.variant || "").localeCompare(String(b.variant || ""));
      });
      return _state.clauses;
    });
  }

  // ── Capture from Word selection (for OOXML-format clauses) ────────
  function _captureSelectionOoxml() {
    return eli.host.runRaw("clause_library:capture_selection", function (context) {
      var sel = context.document.getSelection();
      var ooxml = sel.getOoxml();
      sel.load("text");
      return context.sync().then(function () {
        var text = sel.text || "";
        return { ooxml: ooxml.value || "", text: text };
      });
    });
  }

  // ── Render entry: full overlay (list + edit panel side-by-side) ───
  function _renderOverlay() {
    _closeOverlay();
    var overlay = document.createElement("div");
    overlay.id = "_eli3_cl_overlay";
    overlay.style.cssText =
      "position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(15,23,42,0.55);" +
      "display:flex;align-items:center;justify-content:center;z-index:99998;" +
      "font-family:Inter,system-ui,sans-serif;";
    var card = document.createElement("div");
    card.style.cssText =
      "background:#fff;width:92%;max-width:1080px;height:88vh;" +
      "border:1px solid #cbd5e1;border-radius:0;box-shadow:0 24px 60px rgba(15,23,42,0.45);" +
      "display:flex;flex-direction:column;overflow:hidden;";
    card.innerHTML =
      // Header
      '<div style="background:linear-gradient(135deg,#0d1b2a 0%,#1b263b 100%);padding:14px 20px;border-bottom:3px solid #c9a227;display:flex;justify-content:space-between;align-items:center;">' +
        '<div>' +
          '<div style="font-size:10px;font-weight:800;color:#c9a227;text-transform:uppercase;letter-spacing:0.22em;">Skeleton System · Phase 1</div>' +
          '<div style="font-family:Georgia,serif;font-size:20px;font-weight:800;color:#fff;margin-top:3px;">📚 Clause Library</div>' +
        '</div>' +
        '<button id="_eli3_cl_close" style="background:transparent;border:none;color:#fef3c7;font-size:22px;cursor:pointer;line-height:1;">✕</button>' +
      '</div>' +
      // Body (toolbar + list + edit panel)
      '<div style="flex:1;display:flex;min-height:0;background:#f8fafc;">' +
        '<div id="_eli3_cl_left" style="flex:1;min-width:0;display:flex;flex-direction:column;border-right:1px solid #e2e8f0;">' +
          '<div id="_eli3_cl_toolbar" style="padding:10px 14px;display:flex;gap:8px;align-items:center;background:#fff;border-bottom:1px solid #e2e8f0;flex-wrap:wrap;"></div>' +
          '<div id="_eli3_cl_list" style="flex:1;overflow-y:auto;padding:8px;"></div>' +
        '</div>' +
        '<div id="_eli3_cl_right" style="width:48%;min-width:380px;display:flex;flex-direction:column;background:#fff;"></div>' +
      '</div>';
    overlay.appendChild(card);
    document.body.appendChild(overlay);
    document.getElementById("_eli3_cl_close").onclick = _closeOverlay;
    overlay.onclick = function (ev) { if (ev.target === overlay) _closeOverlay(); };
    _renderToolbar();
    _renderList();
    _renderEditPanel();
  }
  function _closeOverlay() {
    var el = document.getElementById("_eli3_cl_overlay");
    if (el && el.parentNode) el.parentNode.removeChild(el);
  }

  function _renderToolbar() {
    var bar = document.getElementById("_eli3_cl_toolbar");
    if (!bar) return;
    var variants = {};
    _state.clauses.forEach(function (c) { if (c.variant) variants[c.variant] = true; });
    var variantOpts = '<option value="">All variants</option>' +
      Object.keys(variants).sort().map(function (v) {
        return '<option value="' + _esc(v) + '"' + (v === _state.variantFilter ? " selected" : "") + '>' + _esc(v) + '</option>';
      }).join("");
    bar.innerHTML =
      '<input id="_eli3_cl_search" type="text" placeholder="🔍 Search clauses…" value="' + _esc(_state.filter) + '" ' +
        'style="flex:1;min-width:180px;padding:6px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;font-family:inherit;">' +
      '<select id="_eli3_cl_variant" style="padding:6px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;font-family:inherit;">' + variantOpts + '</select>' +
      '<button id="_eli3_cl_new" style="padding:6px 12px;font-size:11px;font-weight:800;color:#fff;background:linear-gradient(180deg,#1565c0,#0d47a1);border:1px solid #0d47a1;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">+ New Clause</button>' +
      '<button id="_eli3_cl_capture" style="padding:6px 12px;font-size:11px;font-weight:800;color:#5a330f;background:linear-gradient(180deg,#fffdf5,#fef3c7);border:1px solid #d6b347;cursor:pointer;text-transform:uppercase;letter-spacing:0.1em;">📥 Capture from Word</button>' +
      '<span id="_eli3_cl_count" style="margin-left:auto;color:#64748b;font-size:11px;"></span>';
    document.getElementById("_eli3_cl_search").oninput = function (e) {
      _state.filter = e.target.value; _renderList();
    };
    document.getElementById("_eli3_cl_variant").onchange = function (e) {
      _state.variantFilter = e.target.value; _renderList();
    };
    document.getElementById("_eli3_cl_new").onclick = function () {
      _state.creating = true; _state.captureMode = false; _state.editId = null;
      _renderEditPanel();
    };
    document.getElementById("_eli3_cl_capture").onclick = function () {
      _captureSelectionOoxml().then(function (cap) {
        if (!cap || (!cap.ooxml && !cap.text)) {
          _toast("Nothing selected in Word — select content first, then click Capture.", "warn");
          return;
        }
        _state.creating = true; _state.captureMode = true; _state.editId = null;
        _state._capturedOoxml = cap.ooxml;
        _state._capturedText = cap.text;
        _renderEditPanel();
      }).catch(function (e) {
        _toast("Capture failed: " + (e && e.message), "err");
      });
    };
  }

  function _renderList() {
    var listEl = document.getElementById("_eli3_cl_list");
    var countEl = document.getElementById("_eli3_cl_count");
    if (!listEl) return;
    var f = String(_state.filter || "").toLowerCase().trim();
    var v = _state.variantFilter;
    var rows = _state.clauses.filter(function (c) {
      if (v && c.variant !== v) return false;
      if (f && (String(c.name || "").toLowerCase().indexOf(f) === -1) &&
              (String(c.body || "").toLowerCase().indexOf(f) === -1)) return false;
      return true;
    });
    if (countEl) countEl.textContent = rows.length + " of " + _state.clauses.length;
    if (!rows.length) {
      listEl.innerHTML =
        '<div style="padding:32px;text-align:center;color:#64748b;font-size:12px;">' +
          (_state.clauses.length === 0
            ? '<div style="font-size:32px;margin-bottom:8px;">📚</div><b>No clauses yet.</b><br>Click <strong>+ New Clause</strong> to start, or <strong>Capture from Word</strong> to grab a formatted block.'
            : '<b>No matches.</b><br>Try a different search.') +
        '</div>';
      return;
    }
    listEl.innerHTML = rows.map(function (c) {
      var preview = String(c.body || "").substring(0, 120).replace(/\s+/g, " ").trim();
      if (preview.length > 110) preview = preview.substring(0, 110) + "…";
      var isActive = (_state.editId === c.id);
      var formBadge = c.format === "ooxml"
        ? '<span style="font-size:9px;font-weight:800;color:#5a330f;background:#fef3c7;border:1px solid #d6b347;padding:1px 5px;letter-spacing:0.1em;text-transform:uppercase;">OOXML</span>'
        : '<span style="font-size:9px;font-weight:800;color:#155e75;background:#cffafe;border:1px solid #67e8f9;padding:1px 5px;letter-spacing:0.1em;text-transform:uppercase;">Plain</span>';
      return '<div class="_eli3_cl_row" data-cl-id="' + _esc(c.id) + '" style="background:' + (isActive ? "#fef9e0" : "#fff") + ';border:1px solid ' + (isActive ? "#c9a227" : "#e2e8f0") + ';border-left:3px solid ' + (isActive ? "#c9a227" : "#cbd5e1") + ';padding:8px 12px;margin-bottom:6px;cursor:pointer;">' +
        '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">' +
          '<div style="min-width:0;flex:1;">' +
            '<div style="font:700 12px/1.2 Inter,sans-serif;color:#0f172a;">' + _esc(c.name) + '</div>' +
            '<div style="font:500 10px/1.3 Inter,sans-serif;color:#64748b;margin-top:2px;">' + _esc(c.variant || "(no variant)") + '</div>' +
            '<div style="font:400 11px/1.4 Georgia,serif;color:#475569;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + _esc(preview) + '</div>' +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:3px;align-items:flex-end;flex-shrink:0;">' +
            formBadge +
            '<span style="font:500 9px/1 Inter,sans-serif;color:#94a3b8;">v' + (c.version || 1) + '</span>' +
          '</div>' +
        '</div>' +
      '</div>';
    }).join("");
    listEl.querySelectorAll("._eli3_cl_row").forEach(function (row) {
      row.onclick = function () {
        var id = row.getAttribute("data-cl-id");
        _state.editId = id; _state.creating = false; _state.captureMode = false;
        _renderList(); _renderEditPanel();
      };
    });
  }

  function _renderEditPanel() {
    var rightEl = document.getElementById("_eli3_cl_right");
    if (!rightEl) return;
    var c;
    if (_state.editId) {
      c = _state.clauses.find(function (x) { return x.id === _state.editId; });
      if (!c) { _state.editId = null; _renderEditPanel(); return; }
    } else if (_state.creating) {
      c = {
        id: "", name: "", variant: "",
        body: _state.captureMode ? (_state._capturedOoxml || "") : "",
        format: _state.captureMode ? "ooxml" : "plain",
        version: 1, modifiedAt: new Date().toISOString(),
      };
    } else {
      rightEl.innerHTML =
        '<div style="padding:48px 32px;text-align:center;color:#94a3b8;font-size:12px;">' +
          '<div style="font-size:36px;margin-bottom:10px;">📋</div>' +
          '<b>Select a clause</b><br>or click <strong>+ New Clause</strong> to create one.' +
        '</div>';
      return;
    }
    var isCreating = _state.creating;
    var isOoxml = c.format === "ooxml";
    var captureNote = (_state.captureMode && _state.creating)
      ? '<div style="background:#fefce8;border:1px solid #fde047;padding:8px 12px;font-size:11px;color:#713f12;margin-bottom:10px;">' +
          '<b>📥 Captured from Word selection.</b><br>' +
          'Preview text (~' + (String(_state._capturedText || "").length) + ' chars). The OOXML body is stored for full-fidelity insertion at resolve time.' +
        '</div>'
      : "";
    var bodyEditor;
    if (isOoxml && !isCreating) {
      // Editing an existing OOXML clause — no inline edit, recapture only.
      bodyEditor =
        '<div style="background:#f8fafc;border:1px dashed #cbd5e1;padding:14px;text-align:center;color:#64748b;font-size:11px;">' +
          '<b>OOXML clause (rich formatting).</b><br>' +
          'To edit, click <strong>📥 Recapture from Word</strong> below — opens the current OOXML in a scratch flow, you edit in Word and recapture.' +
        '</div>' +
        '<div style="font:500 11px/1.4 Georgia,serif;color:#475569;background:#fff;border:1px solid #e2e8f0;padding:10px 12px;margin-top:6px;max-height:200px;overflow-y:auto;white-space:pre-wrap;">' +
        _esc(String(c.body || "").substring(0, 800)) + (String(c.body || "").length > 800 ? "…" : "") +
        '</div>';
    } else {
      var bodyVal = isCreating && _state.captureMode ? (_state._capturedText || "") : (c.body || "");
      bodyEditor =
        captureNote +
        '<textarea id="_eli3_cl_body" placeholder="Clause body text (plain). Use \\n\\n for paragraph breaks." style="width:100%;height:280px;padding:10px 12px;font:500 12px/1.55 Georgia,serif;color:#0f172a;background:#fff;border:1px solid #cbd5e1;resize:vertical;box-sizing:border-box;">' +
        _esc(bodyVal) + '</textarea>';
    }
    rightEl.innerHTML =
      '<div style="padding:14px 16px;border-bottom:1px solid #e2e8f0;background:#f8fafc;">' +
        '<div style="font-size:9.5px;font-weight:800;color:#c9a227;text-transform:uppercase;letter-spacing:0.18em;">' +
          (isCreating ? (_state.captureMode ? "New clause · captured from Word" : "New clause") : "Edit clause") +
        '</div>' +
      '</div>' +
      '<div style="flex:1;overflow-y:auto;padding:14px 16px;">' +
        '<div style="margin-bottom:10px;">' +
          '<label style="display:block;font:800 9.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#475569;margin-bottom:4px;">Clause Name</label>' +
          '<input id="_eli3_cl_name" type="text" value="' + _esc(c.name) + '" placeholder="e.g. Recitals 1, or Limitation of Liability" style="width:100%;padding:7px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;box-sizing:border-box;">' +
          '<div style="font-size:10px;color:#94a3b8;margin-top:3px;">Referenced from skeleton as <code style="font-family:monospace;background:#f1f5f9;padding:1px 4px;">#[' + (_esc(c.name) || "Clause Name") + ']</code></div>' +
        '</div>' +
        '<div style="margin-bottom:10px;">' +
          '<label style="display:block;font:800 9.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#475569;margin-bottom:4px;">Variant</label>' +
          '<input id="_eli3_cl_variant_in" type="text" value="' + _esc(c.variant) + '" placeholder="e.g. Mutual NDA, Services Agreement" style="width:100%;padding:7px 10px;font-size:12px;border:1px solid #cbd5e1;background:#fff;color:#0f172a;box-sizing:border-box;">' +
          '<div style="font-size:10px;color:#94a3b8;margin-top:3px;">Matches the skeleton\'s <code style="font-family:monospace;background:#f1f5f9;padding:1px 4px;">&amp;[' + (_esc(c.variant) || "Variant") + ']</code> declaration (case-insensitive).</div>' +
        '</div>' +
        '<div style="margin-bottom:10px;">' +
          '<label style="display:block;font:800 9.5px/1 Inter,sans-serif;text-transform:uppercase;letter-spacing:0.14em;color:#475569;margin-bottom:4px;">Body (<span id="_eli3_cl_fmt_label">' + (isOoxml ? "OOXML" : "plain text") + '</span>)</label>' +
          bodyEditor +
        '</div>' +
      '</div>' +
      '<div style="padding:12px 16px;border-top:1px solid #e2e8f0;background:#f8fafc;display:flex;gap:8px;justify-content:flex-end;">' +
        (isCreating
          ? ''
          : '<button id="_eli3_cl_delete" style="margin-right:auto;padding:7px 14px;font-size:11px;font-weight:800;color:#991b1b;background:#fff;border:1px solid #fca5a5;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">🗑️ Delete</button>') +
        (isOoxml && !isCreating
          ? '<button id="_eli3_cl_recapture" style="padding:7px 14px;font-size:11px;font-weight:800;color:#5a330f;background:linear-gradient(180deg,#fffdf5,#fef3c7);border:1px solid #d6b347;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">📥 Recapture</button>'
          : '') +
        '<button id="_eli3_cl_cancel" style="padding:7px 14px;font-size:11px;font-weight:800;color:#475569;background:#fff;border:1px solid #cbd5e1;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">Cancel</button>' +
        '<button id="_eli3_cl_save" style="padding:7px 14px;font-size:11px;font-weight:800;color:#fff;background:linear-gradient(180deg,#1565c0,#0d47a1);border:1px solid #0d47a1;cursor:pointer;text-transform:uppercase;letter-spacing:0.08em;">💾 Save</button>' +
      '</div>';
    document.getElementById("_eli3_cl_cancel").onclick = function () {
      _state.editId = null; _state.creating = false; _state.captureMode = false;
      delete _state._capturedOoxml; delete _state._capturedText;
      _renderList(); _renderEditPanel();
    };
    document.getElementById("_eli3_cl_save").onclick = function () {
      var name = document.getElementById("_eli3_cl_name").value.trim();
      var variant = document.getElementById("_eli3_cl_variant_in").value.trim();
      var bodyEl = document.getElementById("_eli3_cl_body");
      var body;
      if (isOoxml && !isCreating) {
        body = c.body; // unchanged (recapture flow only changes body)
      } else if (_state.captureMode && _state.creating) {
        body = _state._capturedOoxml || "";
      } else {
        body = (bodyEl && bodyEl.value) || "";
      }
      if (!name) { _toast("Name required.", "warn"); return; }
      var format = isOoxml ? "ooxml" : "plain";
      var newId = isCreating ? _clauseId(name, variant) : c.id;
      var row = {
        id: newId,
        name: name,
        variant: variant,
        body: body,
        format: format,
        version: isCreating ? 1 : (Number(c.version || 0) + 1),
        modifiedAt: new Date().toISOString(),
        modifiedBy: userEmail || null,
      };
      eli.storage.put("bd_clauses", row).then(function () {
        return _loadAll();
      }).then(function () {
        _state.editId = row.id; _state.creating = false; _state.captureMode = false;
        delete _state._capturedOoxml; delete _state._capturedText;
        _renderList(); _renderEditPanel();
        _toast(isCreating ? "✅ Clause created" : "✅ Clause saved (v" + row.version + ")", "ok");
      }).catch(function (e) {
        _toast("Save failed: " + (e && e.message), "err");
      });
    };
    var delBtn = document.getElementById("_eli3_cl_delete");
    if (delBtn) delBtn.onclick = function () {
      eli.events.safeAsync(eli.ui.confirm({
        title: "Delete clause?",
        message: "Delete '" + (c.name || "this clause") + "' (" + (c.variant || "no variant") + ")?",
      }), "clause_library.delete_confirm").then(function (ok) {
        if (!ok) return;
        return eli.storage.delete("bd_clauses", c.id).then(function () {
          return _loadAll();
        }).then(function () {
          _state.editId = null;
          _renderList(); _renderEditPanel();
          _toast("🗑️ Deleted", "ok");
        });
      });
    };
    var recapBtn = document.getElementById("_eli3_cl_recapture");
    if (recapBtn) recapBtn.onclick = function () {
      _captureSelectionOoxml().then(function (cap) {
        if (!cap || !cap.ooxml) {
          _toast("Nothing selected in Word — select replacement content first.", "warn");
          return;
        }
        c.body = cap.ooxml;
        c.version = Number(c.version || 0) + 1;
        c.modifiedAt = new Date().toISOString();
        return eli.storage.put("bd_clauses", c).then(function () {
          return _loadAll();
        }).then(function () {
          _renderList(); _renderEditPanel();
          _toast("✅ Recaptured (v" + c.version + ")", "ok");
        });
      });
    };
  }

  // ── Tile / dispatch entry ─────────────────────────────────────────
  function _open() {
    _loadAll().then(function () { _renderOverlay(); }).catch(function (e) {
      eli.log.event("tool", "clause_library_open_failed", { msg: e && e.message });
      _toast("Failed to load clauses: " + (e && e.message), "err");
    });
  }

  eli.register({
    tile: { app_clause_library: _open },
    clauses: {
      open: _open,
      getAll: function () { return eli.storage.getAll("bd_clauses"); },
      lookup: function (name, variant) {
        // Lookup with variant fallback: exact (name+variant), then
        // name+"" (no variant), then null. Case-insensitive variant.
        return eli.storage.getAll("bd_clauses").then(function (rows) {
          rows = rows || [];
          var nl = String(name || "").toLowerCase().trim();
          var vl = String(variant || "").toLowerCase().trim();
          var exact = rows.find(function (r) {
            return String(r.name || "").toLowerCase().trim() === nl &&
                   String(r.variant || "").toLowerCase().trim() === vl;
          });
          if (exact) return exact;
          // Fallback: clause with same name and ANY variant (last-wins).
          var any = rows.filter(function (r) {
            return String(r.name || "").toLowerCase().trim() === nl;
          });
          if (any.length === 1) return any[0]; // single-variant clause works for any variant
          return null;
        });
      },
    },
  });
  eli.log.event("tool", "clause_library_init", { email: userEmail });
}
